const getStatusColor = (status: string) => {
  switch (status) {
    case 'completed':
      return 'text-green-400';
    case 'indexing':
      return 'text-[#5ea9ea]';
    case 'failed':
      return 'text-red-400';
    default:
      return 'text-yellow-400';

